  }

  if (!charAt(src, pos)) {
    throw new GrammarParseError(
      src,
      pos,
      'Unexpected end of grammar input, failed to complete parse'
    );
  }
  const codePoint = src.codePointAt(pos) as number;
  return [codePoint, codePoint > 0xffff ? 2 : 1];
};

