import json
import sys

sys.path.insert(0, "/workspace/reference_implementation")

from gbnf import GBNF  # noqa: E402
from gbnf.utils.errors.grammar_parse_error import GrammarParseError  # noqa: E402
from gbnf.utils.errors.input_parse_error import InputParseError  # noqa: E402


def rules_of(state):
    out = []
    for rule in state:
        if rule.type.value == "end":
            out.append({"type": "end"})
        else:
            out.append(
                {
                    "type": rule.type.value,
                    "value": [list(v) if isinstance(v, tuple) else v for v in rule.value],
                }
            )
    return out


def run(grammar, inputs):
    """Walk the grammar one input character at a time, recording state at each step."""
    steps = []
    try:
        state = GBNF(grammar)
    except GrammarParseError as err:
        return {"error": "grammar", "message": str(err), "pos": err.pos, "reason": err.reason}
    except Exception as err:  # noqa: BLE001
        return {"error": "other", "message": f"{type(err).__name__}: {err}"}
    steps.append(rules_of(state))
    for char in inputs:
        try:
            state = state.add(char)
        except InputParseError as err:
            return {"error": "input", "message": str(err), "recent": err.error_for_most_recent_input, "steps": steps}
        except Exception as err:  # noqa: BLE001
            return {"error": "other", "message": f"{type(err).__name__}: {err}", "steps": steps}
        steps.append(rules_of(state))
    return {"error": None, "steps": steps}


cases = json.load(open(sys.argv[1]))
print(json.dumps([run(g, i) for g, i in cases]))

